"""Inspect files generated by notice-only.cjs, including the mixed-document boundary."""
from pathlib import Path
import subprocess
import xml.etree.ElementTree as ET
import zipfile

out = Path('.test-output')
ns = {'p': 'http://www.hancom.co.kr/hwpml/2011/paragraph'}
for name, mixed in [('notice-only', False), ('notice-mixed', True)]:
    with zipfile.ZipFile(out / (name + '.hwpx')) as archive:
        body = ET.fromstring(archive.read('Contents/section0.xml'))
    tables = body.findall('.//p:tbl', ns)
    frames = [t for t in tables if t.get('rowCnt') == '1' and t.get('colCnt') == '1']
    assert len(frames) == int(mixed), (name, 'HWPX outer notice frame')
    headings = [p for p in body.findall('.//p:p', ns) if ''.join(p.itertext()) == '고지사항']
    assert len(headings) == int(mixed), (name, 'HWPX notice heading')
    assert any(t.get('colCnt') == '4' for t in tables), 'Notice table must remain'
    text = subprocess.check_output(['pdftotext', '-raw', str(out / (name + '.pdf')), '-'], text=True)
    assert ('고지사항' in text.splitlines()) == mixed, (name, 'PDF notice heading')
    assert all(word in text for word in ['개인정보 항목', '법적 근거', '성명']), 'PDF table content must remain'
    print('PASS', name, 'HWPX structure and PDF heading/table text')

try:
    import fitz
except ImportError:
    print('SKIP PDF drawing inspection: optional PyMuPDF is unavailable')
else:
    for name, mixed in [('notice-only', False), ('notice-mixed', True)]:
        with fitz.open(out / (name + '.pdf')) as pdf:
            outer_frames = [drawing for page in pdf for drawing in page.get_drawings()
                            if abs(drawing['rect'].width - (595.28 - 2 * 56.69 + 12)) < .05]
        assert bool(outer_frames) == mixed, (name, 'PDF outer notice frame')
        print('PASS', name, 'PDF outer border condition')
